<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Campaign extends Model{protected $guarded=[]; protected $casts=['start_date'=>'date','end_date'=>'date']; public function tenant(){return $this->belongsTo(Tenant::class);} public function topic(){return $this->belongsTo(Topic::class);} public function channel(){return $this->belongsTo(Channel::class);} public function assets(){return $this->belongsToMany(ContentAsset::class,'campaign_asset');} public function performanceEntries(){return $this->hasMany(PerformanceEntry::class);} public static function statuses(){return ['idea'=>'Idee','planned'=>'Geplant','in_progress'=>'In Arbeit','published'=>'Veröffentlicht','evaluated'=>'Ausgewertet','archived'=>'Archiv'];}}
